contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 burnAmount) public {
        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalanceBefore = c.balanceOf(address(this));
        require(ownerBalanceBefore >= burnAmount);

        bool reverted;
        try c.burn(burnAmount) { reverted = false; } catch { reverted = true; }

        if (!reverted) {
            assert(c.totalSupply() == supplyBefore - burnAmount);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address other, uint256 burnAmount) public {
        require(other != address(0));
        require(other != address(this));
        require(burnAmount <= c.balanceOf(address(this)));

        uint256 beforeSupply = c.totalSupply();
        uint256 beforeSelfBal = c.balanceOf(address(this));
        uint256 beforeOtherBal = c.balanceOf(other);

        c.burn(burnAmount);

        uint256 afterSupply = c.totalSupply();
        uint256 afterSelfBal = c.balanceOf(address(this));
        uint256 afterOtherBal = c.balanceOf(other);

        assert(afterSupply == beforeSupply - burnAmount);
        assert(afterSelfBal == beforeSelfBal - burnAmount);
        assert(afterOtherBal == beforeOtherBal);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, bool asOther) public payable {
        address before = c.owner();
        bool reverted;
        if (asOther) {
            require(caller != address(this));
            (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
            reverted = !ok;
        } else {
            try c.owned() { reverted = false; } catch { reverted = true; }
        }
        address afterOwner = c.owner();
        assert(!reverted == !asOther);
        assert(afterOwner == before);
    }
}

