    }

    function run(uint256 burnValue) public {
        require(burnValue > 0);

        uint256 ownerBalanceBefore = c.balanceOf(address(this));
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        try c.burn(burnValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ownerBalanceAfter = c.balanceOf(address(this));
        uint256 totalSupplyAfter = c.totalSupply();

        if (reverted) {
